1|// Spike 1: can our own program drive Muse Code through Meta's SDK?
2|// Spawns `muse serve`, opens a session in a scratch folder, sends one turn,
3|// streams the reply. No approval handler, so tool use falls to the server's
4|// default-deny. Usage: node hello.mjs "<prompt>"
5|import { MuseClient } from "@muse-code/sdk";
6|import { mkdirSync } from "node:fs";
7|
8|const museBin = process.env.MUSE_BIN ?? "muse";
9|const workspaceRoot = process.env.MUSE_WS ?? "C:\\muse-play\\spike-ws";
10|const prompt = process.argv[2] ?? "In one short sentence, say hello and tell me which model you are. Don't use any tools.";
11|
12|mkdirSync(workspaceRoot, { recursive: true });
13|const t0 = Date.now();
14|const client = await MuseClient.spawn({
15|  museBin,
16|  args: ["serve", ...(process.env.MUSE_TRUST ? ["--trust-workspace"] : [])], // --trust-workspace: load the workspace's AGENTS.md/rules
17|  clientInfo: { name: "meta_betta_spike", version: "0.0.1" }, // must match ^[a-z0-9_]+$ (the SDK README's "my-app" would be rejected)
18|});
19|console.log(`[host up in ${Date.now() - t0} ms]`);
20|
21|const session = await client.startSession({ workspaceRoot });
22|console.log(`[session ${session.sessionId}]`);
23|
24|const turn = await session.sendUserTurn({ input: [{ type: "text", text: prompt }] });
25|for await (const d of turn.deltas()) process.stdout.write(typeof d === "string" ? d : (d.text ?? d.delta ?? ""));
26|const outcome = await turn.completed;
27|console.log(`\n[turn done: ${JSON.stringify(outcome).slice(0, 300)}]`);
28|console.log(`[total ${Date.now() - t0} ms]`);
29|await client.close();

